language sql security definer set search_path = pg_catalog, pg_temp
as $stackra$
select c.tx, c.seq, c.tenant_id from outbox.changes c
where c.tx < pg_snapshot_xmin(pg_current_snapshot())
and c.type in (select jsonb_array_elements_text(models))
and (after_tx is null or (c.tx, c.seq) > (after_tx, after_seq))
order by c.tx, c.seq limit max_rows
$stackra$;
revoke all on function "outbox"."claim_changes"(xid8, bigint, jsonb, integer) from public;
grant "stackra_system_access" to current_user;
grant create on schema "outbox" to "stackra_system_access";
alter function "outbox"."claim_changes"(xid8, bigint, jsonb, integer) owner to "stackra_system_access";
revoke create on schema "outbox" from "stackra_system_access";
grant execute on function "outbox"."claim_changes"(xid8, bigint, jsonb, integer) to current_user;
revoke "stackra_system_access" from current_user;
-- stackra:system-function outbox.change_position_at a replay moves a cursor to an instant of the whole log, every tenant's entries included;
do $$
begin
  create role "stackra_system_access" nologin nobypassrls;
exception when duplicate_object then null;
end
$$;
create function "outbox"."change_position_at"("at_or_after" timestamptz) returns table ("tx" xid8, "seq" bigint, "latest" boolean)
language sql security definer set search_path = pg_catalog, pg_temp
as $stackra$
(select c.tx, c.seq, false from outbox.changes c where c.occurred_at >= at_or_after
  order by c.tx, c.seq limit 1)
union all
(select c.tx, c.seq, true from outbox.changes c order by c.tx desc, c.seq desc limit 1)
$stackra$;
revoke all on function "outbox"."change_position_at"(timestamptz) from public;
grant "stackra_system_access" to current_user;
grant create on schema "outbox" to "stackra_system_access";
alter function "outbox"."change_position_at"(timestamptz) owner to "stackra_system_access";
revoke create on schema "outbox" from "stackra_system_access";
grant execute on function "outbox"."change_position_at"(timestamptz) to current_user;
revoke "stackra_system_access" from current_user;
-- stackra:system-function outbox.claim_expired_changes the change log's retention claims expired default-partition rows of every tenant, then deletes per tenant;
do $$
begin
  create role "stackra_system_access" nologin nobypassrls;
exception when duplicate_object then null;
end
$$;
create function "outbox"."claim_expired_changes"("expired_before" timestamptz, "max_rows" integer) returns table ("tx" xid8, "seq" bigint, "tenant_id" varchar(33))
language sql security definer set search_path = pg_catalog, pg_temp
as $stackra$
select c.tx, c.seq, c.tenant_id from outbox.changes_default c
where c.occurred_at < expired_before order by c.tx, c.seq limit max_rows
$stackra$;
revoke all on function "outbox"."claim_expired_changes"(timestamptz, integer) from public;
grant "stackra_system_access" to current_user;
grant create on schema "outbox" to "stackra_system_access";
alter function "outbox"."claim_expired_changes"(timestamptz, integer) owner to "stackra_system_access";
revoke create on schema "outbox" from "stackra_system_access";
grant execute on function "outbox"."claim_expired_changes"(timestamptz, integer) to current_user;
revoke "stackra_system_access" from current_user;
